  (data.customers||[]).forEach((c,i)=>{const id=String(c.id||c.email||("customer-"+i));customerStore.put({...c,id,source,lastSyncedAt:data.generatedAt||new Date().toISOString()});(c.ordersHistory||[]).forEach((o,j)=>{const oid=String(o.id||o.name||`${id}-${String(o.date||o.createdAt||"").slice(0,19)}-${j}`);orderStore.put({...o,id:oid,customerId:id,customerEmail:c.email||"",source,lastSyncedAt:data.generatedAt||new Date().toISOString()})})});
