  (data.products||data.catalogSample||[]).forEach((p,pi)=>(p.variants||[]).forEach((v,vi)=>{if(!v.sku)return;productStore.put({...v,sku:String(v.sku),product:p.title||p.product||"",vendor:p.vendor||"",type:p.type||p.productType||"",totalProductStock:+(p.stock??p.totalInventory??0)||0,source,lastSyncedAt:data.generatedAt||new Date().toISOString()})}));
