function decodeShopifySyncFragment(){
  try{
    const h=location.hash||"";if(!h.startsWith("#shopify-sync="))return null;
    const raw=h.slice(14),b64=raw.replace(/-/g,"+").replace(/_/g,"/"),pad=b64+"=".repeat((4-b64.length%4)%4);
    const bin=atob(pad),bytes=Uint8Array.from(bin,c=>c.charCodeAt(0));return JSON.parse(new TextDecoder().decode(bytes))
  }catch(e){console.error("Shopify sync fragment:",e);return null}
}
