async function loadShopifyQaFixture(){
  if(!QA_MODE||typeof state==="undefined"||!Array.isArray(state.clients))return;
  try{
    const r=await fetch("qa-shopify-fixture.json?v=20260920-live1",{cache:"no-store"});
    if(!r.ok)throw new Error("HTTP "+r.status);
    qaFixture=await r.json();
    window.B2B_QA_DATA=qaFixture;
    const base=920000, customers=qaFixture.b2bCustomerSample||[], orders=qaFixture.recentOrders||[];
    const existing=new Set(state.clients.map(c=>String(c.id)));
    customers.forEach((q,i)=>{
      const id=base+i;if(existing.has(String(id)))return;
      const assigned=orders.filter((_,j)=>j%Math.max(1,customers.length)===i).slice(0,Math.max(1,Math.min(5,q.ordersCount||1)));
      const fallback=orders[i%Math.max(1,orders.length)];
      const hist=(assigned.length?assigned:(fallback?[fallback]:[])).map(o=>({date:String(o.date||"").slice(0,10),amount:+o.total||0,total:+o.total||0}));
      const last=hist[0]?.date||qaDate(-(7+i%70));
      state.clients.push({
        id,cliente:q.customer||("Cliente B2B "+(i+1)),contacto:q.customer||("Cliente B2B "+(i+1)),
        email:"qa.b2b"+(i+1)+"@example.test",ultimaB2B:last,ultima:last,
        reorderMedian:[30,45,60,75][i%4],reorderDays:[30,45,60,75][i%4],
        b2bConfirmedOrders:+q.ordersCount||2,pedidos:+q.ordersCount||2,
        totalSpent:+q.totalSpent||0,ordersHistory:hist,qaShopify:true
      });
    });
    const cats=qaFixture.catalogSample||[];
    incoming=(cats.slice(0,8).flatMap((p,i)=>(p.variants||[]).slice(0,1).map(v=>({
      sku:v.sku||("QA-SKU-"+i),product:p.title||"Producto Shopify",qty:24+(i*12),eta:qaDate(4+i*2)
    })))).filter(x=>x.sku);
    waiting=[];nextActions=[];pipeline={};
    customers.slice(0,20).forEach((q,i)=>{
      const id=base+i;
      pipeline[id]={stage:STAGES[i%STAGES.length],amount:i%6===5?Math.round((+q.totalSpent||0)/Math.max(1,+q.ordersCount||1)):0,updatedAt:new Date().toISOString()};
      nextActions.push({id:"qa-shopify-action-"+i,clientId:id,type:["Seguimiento","Cotización","Recompra","Llamada"][i%4],date:qaDate((i%5)-2),note:"QA Shopify.",done:false,createdAt:new Date().toISOString()});
      if(i<Math.min(6,incoming.length)){waiting.push({clientId:id,sku:incoming[i].sku,product:incoming[i].product,note:"QA: cliente en espera",active:true,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()})}
    });
    localStorage.setItem(KEY,JSON.stringify(incoming));
    localStorage.setItem(WAIT_KEY,JSON.stringify(waiting));
    localStorage.setItem(TASK_KEY,JSON.stringify(nextActions));
    localStorage.setItem(PIPE_KEY,JSON.stringify(pipeline));
    document.documentElement.dataset.qaMode="shopify";
    const old=document.querySelector(".qaModeBadge");if(old)old.remove();
    const badge=document.createElement("div");badge.className="qaModeBadge";badge.textContent="MODO QA · SHOPIFY";document.body.appendChild(badge);
  }catch(e){
    console.error("QA Shopify fixture:",e);
    const badge=document.createElement("div");badge.className="qaModeBadge";badge.textContent="QA · ERROR CARGANDO SHOPIFY";document.body.appendChild(badge);
  }
}
function excelDate(v){if(!v)return"";if(v instanceof Date&&!isNaN(v))return v.toISOString().slice(0,10);if(typeof v==="number"){const d=new Date(Math.round((v-25569)*86400000));return isNaN(d)?"":d.toISOString().slice(0,10)}const d=new Date(v);return isNaN(d)?String(v).slice(0,10):d.toISOString().slice(0,10)}
function getCol(r,terms){for(const k of Object.keys(r)){const z=k.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"");if(terms.some(t=>z.includes(t)))return r[k]}return""}
function waitingKey(clientId,sku){return String(clientId)+"|"+norm(sku)}
function isWaiting(clientId,sku){return waiting.some(w=>waitingKey(w.clientId,w.sku)===waitingKey(clientId,sku)&&w.active!==false)}
function saveWaiting(){localStorage.setItem(WAIT_KEY,JSON.stringify(waiting))}
function setWaiting(clientId,sku,product,note=""){if(window.CRMUsers&&!CRMUsers.guard("write",clientId))return;const key=waitingKey(clientId,sku),i=waiting.findIndex(w=>waitingKey(w.clientId,w.sku)===key);const row={clientId,sku,product:product||"",note,active:true,createdAt:i>=0?waiting[i].createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};if(i>=0)waiting[i]={...waiting[i],...row};else waiting.unshift(row);saveWaiting();window.CRMUsers?.audit("waiting_sku_added","waiting_sku",sku,`Marcó al cliente esperando ${product||sku}`,{row},clientId);renderIncoming();addTodayAlert(true)}
function clearWaiting(clientId,sku){if(window.CRMUsers&&!CRMUsers.guard("write",clientId))return;const w=waiting.find(x=>waitingKey(x.clientId,x.sku)===waitingKey(clientId,sku));if(w){w.active=false;w.updatedAt=new Date().toISOString();saveWaiting();window.CRMUsers?.audit("waiting_sku_cleared","waiting_sku",sku,`Cerró la espera del SKU ${sku}`,{waiting:w},clientId);renderIncoming();addTodayAlert(true)}}
function alerts(){const out=[];for(const x of incoming){const sk=norm(x.sku);for(const [email,hist] of Object.entries(typeof SKU_HISTORY_90D!=="undefined"?SKU_HISTORY_90D:{})){const h=(hist||[]).find(y=>norm(y.sku)===sk);if(!h)continue;const c=(state?.clients||[]).find(z=>norm(z.email)===norm(email));if(!c)continue;const bc=typeof BC_STOCK_BY_SKU!=="undefined"?(BC_STOCK_BY_SKU[x.sku]?.stock??h.bc??0):(h.bc??0);if(+bc>0)continue;const orders=+h.orders||0,units=+h.units||0;if(orders<2&&units<2)continue;out.push({client:c.cliente||c.contacto||email,id:c.id,email,sku:x.sku,product:x.product||h.product,qty:x.qty,eta:x.eta,orders,units,bc,waiting:isWaiting(c.id,x.sku),frequency:orders>=3?"Frecuente":"Recurrente"})}}for(const w of waiting.filter(x=>x.active!==false)){const inc=incoming.find(x=>norm(x.sku)===norm(w.sku));if(!inc)continue;if(out.some(x=>waitingKey(x.id,x.sku)===waitingKey(w.clientId,w.sku)))continue;const c=(state?.clients||[]).find(x=>x.id==w.clientId);if(!c)continue;const hist=(typeof SKU_HISTORY_90D!=="undefined"?SKU_HISTORY_90D[norm(c.email)]||SKU_HISTORY_90D[c.email]||[]:[]).find(h=>norm(h.sku)===norm(inc.sku));const bc=typeof BC_STOCK_BY_SKU!=="undefined"?(BC_STOCK_BY_SKU[inc.sku]?.stock??hist?.bc??0):(hist?.bc??0);if(+bc>0)continue;const orders=+hist?.orders||0,units=+hist?.units||0;if(orders<2&&units<2)continue;out.push({client:c.cliente||c.contacto||c.email||"Cliente",id:c.id,email:c.email||"",sku:inc.sku,product:inc.product||w.product||hist?.product,qty:inc.qty,eta:inc.eta,orders,units,bc,waiting:true,frequency:orders>=3?"Frecuente":"Recurrente"})}return out.sort((a,b)=>(b.waiting-a.waiting)||(b.units-a.units)||(b.orders-a.orders)||((a.eta||"9999").localeCompare(b.eta||"9999")))}
function filteredAlerts(){const q=norm(incomingQuery);return alerts().filter(x=>!q||norm([x.client,x.email,x.sku,x.product].join(" ")).includes(q))}
function renderIncoming(){const a=filteredAlerts(),k=document.getElementById("incomingKpis"),tb=document.getElementById("incomingRows");if(!k||!tb)return;k.innerHTML=[["SKU por llegar",incoming.length],["Unidades",incoming.reduce((s,x)=>s+(+x.qty||0),0)],["Oportunidades reposición",a.length],["Clientes frecuentes",new Set(a.map(x=>x.id)).size]].map(x=>`<div class="kpi"><span>${x[0]}</span><b>${x[1]}</b></div>`).join("");if(incomingView==="sku"){tb.innerHTML=a.length?a.map(x=>`<tr data-client="${x.id}"><td><b>${esc(x.client)}</b><br><small>${esc(x.email)}</small></td><td><b>${esc(x.sku)}</b><br><small>${esc(x.product)}</small></td><td>${x.qty}</td><td>${x.eta||"Sin fecha"}</td><td>${x.orders} compras / ${x.units} u. compradas</td><td>${x.waiting?'<span class="v10badge wait">ESPERANDO</span><br>':""}<span class="v10badge ${x.bc>30?"now":"soon"}">${x.bc>30?"Disponible ahora":"Próximo ingreso"}</span><br><small>BC: ${x.bc}</small></td></tr>`).join(""):'<tr><td colspan="6">Sin coincidencias.</td></tr>'}else{const groups=new Map();a.forEach(x=>{if(!groups.has(x.id))groups.set(x.id,{client:x.client,email:x.email,id:x.id,items:[]});groups.get(x.id).items.push(x)});tb.innerHTML=groups.size?[...groups.values()].map(g=>`<tr class="clientGroup" data-client="${g.id}"><td><b>${esc(g.client)}</b><br><small>${esc(g.email)}</small><br><span class="groupCount">${g.items.length} SKU</span></td><td colspan="4"><div class="skuBundle">${g.items.map(x=>`<div class="skuItem"><div><b>${esc(x.sku)}</b><span>${esc(x.product)}</span></div><div><small>Por llegar</small><b>${x.qty}</b></div><div><small>ETA</small><b>${x.eta||"Sin fecha"}</b></div><div><small>Historial</small><b>${x.orders} compras / ${x.units} u.</b></div><div>${x.waiting?'<span class="v10badge wait">ESPERANDO</span>':`<span class="v10badge ${x.bc>30?"now":"soon"}">${x.bc>30?"Disponible":"Por llegar"}</span>`}<small>BC: ${x.bc}</small></div></div>`).join("")}</div></td><td><button class="miniOpen" data-open="${g.id}">Gestionar cliente</button></td></tr>`).join(""):'<tr><td colspan="6">Sin coincidencias.</td></tr>'}tb.querySelectorAll("[data-open]").forEach(btn=>btn.onclick=e=>{e.stopPropagation();const id=+btn.dataset.open;if(typeof openClient==="function")openClient(id)});tb.querySelectorAll("tr[data-client]").forEach(tr=>tr.onclick=()=>{const id=+tr.dataset.client;if(typeof openClient==="function")openClient(id)})}
function addIncoming(){const tabs=document.querySelector(".tabs");if(!tabs||document.getElementById("incoming"))return;const btn=document.createElement("button");btn.className="tab";btn.dataset.tab="incoming";btn.textContent="Próximos ingresos";tabs.appendChild(btn);const sec=document.createElement("section");sec.id="incoming";sec.className="panel";sec.innerHTML=`<div class="topline"><div><h2>Radar de próximos ingresos</h2><p>Sube el Excel de mercadería por llegar. Muestra únicamente SKU sin stock actual que vienen en camino y clientes que los compran de forma recurrente. Incluye cuánto compró antes cada cliente.</p></div></div><div class="v10upload"><input id="incomingFile" type="file" accept=".xlsx,.xls"><button class="primary" id="incomingRead">Leer Excel</button><button class="soft" id="incomingClear">Limpiar ingresos</button><div id="incomingPreview" class="note">No se reemplaza el stock actual. Esta carga es una capa comercial separada.</div></div><div class="incomingTools"><div class="segmented"><button class="active" data-inview="client">Por cliente</button><button data-inview="sku">Por SKU</button></div><input id="incomingSearch" placeholder="Filtrar por cliente, SKU o producto"></div><div class="kpis" id="incomingKpis"></div><div class="table-wrap"><table><thead><tr><th>Cliente</th><th>SKU / producto</th><th>Por llegar</th><th>Fecha estimada</th><th>Compras anteriores</th><th>Estado</th></tr></thead><tbody id="incomingRows"></tbody></table></div></section>`;document.querySelector("main")?.appendChild(sec)||tabs.parentNode.appendChild(sec);btn.onclick=()=>{document.querySelectorAll(".tab").forEach(x=>x.classList.remove("active"));document.querySelectorAll(".panel").forEach(x=>x.classList.remove("active"));btn.classList.add("active");sec.classList.add("active");renderIncoming()};sec.querySelectorAll("[data-inview]").forEach(v=>v.onclick=()=>{incomingView=v.dataset.inview;sec.querySelectorAll("[data-inview]").forEach(x=>x.classList.toggle("active",x===v));renderIncoming()});document.getElementById("incomingSearch").oninput=e=>{incomingQuery=e.target.value;renderIncoming()};document.getElementById("incomingRead").onclick=readExcel;document.getElementById("incomingClear").onclick=()=>{if(confirm("¿Limpiar la mercadería por llegar cargada?")){incoming=[];localStorage.removeItem(KEY);renderIncoming()}};renderIncoming()}
function readExcel(){const f=document.getElementById("incomingFile")?.files?.[0],pv=document.getElementById("incomingPreview");if(!f)return pv.textContent="Selecciona un Excel.";if(typeof XLSX==="undefined")return pv.textContent="El lector Excel no cargó. Recarga la página e intenta nuevamente.";const r=new FileReader();r.onload=()=>{try{const wb=XLSX.read(r.result,{type:"array",cellDates:true});let rows=[];for(const sh of wb.SheetNames){const x=XLSX.utils.sheet_to_json(wb.Sheets[sh],{defval:""});if(x.length){rows=x;break}}const mapped=rows.map((x,i)=>({sku:String(getCol(x,["sku","codigo","código"])).trim(),qty:+String(getCol(x,["cantidad","qty","unidades"])).replace(/[^0-9.-]/g,"")||0,eta:excelDate(getCol(x,["fecha estimada","fecha llegada","eta","llegada","arribo"])),product:String(getCol(x,["producto","nombre","descripcion","descripción"])).trim(),row:i+2})).filter(x=>x.sku);if(!mapped.length)throw Error("No encontré una columna SKU/Código.");const map=new Map(incoming.map(x=>[norm(x.sku),x]));mapped.forEach(x=>map.set(norm(x.sku),{...(map.get(norm(x.sku))||{}),...x,updatedAt:new Date().toISOString()}));incoming=[...map.values()];localStorage.setItem(KEY,JSON.stringify(incoming));pv.innerHTML=`<b>${mapped.length} SKU leídos</b> · ${mapped.reduce((s,x)=>s+x.qty,0)} unidades. Se cruzaron con el historial B2B.`;renderIncoming()}catch(e){pv.textContent="No pude leer el Excel: "+e.message}};r.readAsArrayBuffer(f)}
function injectWaitingIntoClient(){const panel=document.getElementById("clientPanel")||document.querySelector(".drawer");if(!panel||panel.dataset.waitObserver)return;panel.dataset.waitObserver="1";new MutationObserver(()=>{const detail=document.getElementById("clientDetail")||panel;const txt=detail.innerText||"";if(!panel.classList.contains("open")&&getComputedStyle(panel).display==="none")return;if(detail.querySelector(".waitSkuBox"))return;const email=[...detail.querySelectorAll("p,small,span,div")].map(x=>x.textContent).find(x=>/@/.test(x))||"";const c=(state?.clients||[]).find(x=>email.includes(x.email||""));if(!c)return;const box=document.createElement("div");box.className="waitSkuBox";box.innerHTML='<h3>Cliente esperando SKU</h3><p>Registra un producto que este cliente pidió aunque hoy no tenga stock. Cuando aparezca en Próximos ingresos quedará como prioridad.</p><input class="waitSku" placeholder="SKU"><input class="waitProduct" placeholder="Producto (opcional)"><input class="waitNote" placeholder="Nota (opcional)"><button class="primary">Marcar como esperando</button><div class="waitList"></div>';detail.appendChild(box);const draw=()=>{box.querySelector(".waitList").innerHTML=waiting.filter(w=>w.clientId==c.id&&w.active!==false).map(w=>`<div><b>${esc(w.sku)}</b> ${esc(w.product||"")} <button class="miniDone" data-sku="${esc(w.sku)}">Resolver</button></div>`).join("")||"<small>Sin SKU pendientes.</small>";box.querySelectorAll(".miniDone").forEach(b=>b.onclick=()=>{clearWaiting(c.id,b.dataset.sku);draw()})};box.querySelector(".primary").onclick=()=>{const sku=box.querySelector(".waitSku").value.trim();if(!sku)return alert("Ingresa el SKU.");setWaiting(c.id,sku,box.querySelector(".waitProduct").value,box.querySelector(".waitNote").value);box.querySelector(".waitSku").value="";box.querySelector(".waitProduct").value="";box.querySelector(".waitNote").value="";draw()};draw()}).observe(panel,{childList:true,subtree:true})}
const STAGES=["Detectado","Contactado","Respondió","Oportunidad","Propuesta","Pedido","Recompra"];
function pipeOf(id){return pipeline[id]||{stage:"Detectado",amount:0,updatedAt:""}}
function savePipe(){localStorage.setItem(PIPE_KEY,JSON.stringify(pipeline))}
function setStage(id,stage,amount=0){if(window.CRMUsers&&!CRMUsers.guard("write",id))return;const before={...pipeOf(id)};pipeline[id]={...before,stage,amount:+amount||before.amount||0,updatedAt:new Date().toISOString()};savePipe();window.CRMUsers?.syncPipeline(id,pipeline[id],before);renderPipeline();renderMvpDashboard()}
function renderPipeline(){const host=document.getElementById("mvpPipeline");if(!host)return;const cs=state?.clients||[];host.innerHTML=STAGES.map(st=>{const ids=cs.filter(c=>pipeOf(c.id).stage===st);const amount=ids.reduce((a,c)=>a+(+pipeOf(c.id).amount||0),0);return `<div class="pipeStage"><small>${st}</small><b>${ids.length}</b><span>${st==="Pedido"||st==="Recompra"?new Intl.NumberFormat("es-CL",{style:"currency",currency:"CLP",maximumFractionDigits:0}).format(amount):"clientes"}</span></div>`}).join("")}
function renderMvpDashboard(){const host=document.getElementById("mvpDash");if(!host)return;const cs=state?.clients||[],today=new Date(),active=cs.filter(c=>{const d=ds(getLast(c));return d!=null&&d<=90}).length,risk=cs.filter(c=>clientPriority(c).p==="P1").length,won=Object.values(pipeline).filter(x=>["Pedido","Recompra"].includes(x.stage)).reduce((a,x)=>a+(+x.amount||0),0),managed=Object.keys(pipeline).filter(id=>pipeOf(id).stage!=="Detectado").length;host.innerHTML=[["Cartera",cs.length],["Activos ≤90d",active],["En riesgo/P1",risk],["Gestionados",managed],["$ CRM",new Intl.NumberFormat("es-CL",{style:"currency",currency:"CLP",maximumFractionDigits:0}).format(won)]].map(x=>`<div class="kpi"><span>${x[0]}</span><b>${x[1]}</b></div>`).join("")}
function addMvpDashboard(){const hoy=document.getElementById("hoy");if(!hoy||document.getElementById("mvpDashWrap"))return;const w=document.createElement("div");w.id="mvpDashWrap";w.className="mvpDashWrap";w.innerHTML='<div class="mvpTitle"><small>CONTROL COMERCIAL</small><h2>Dashboard MVP</h2></div><div id="mvpDash" class="kpis"></div><h3>Pipeline</h3><div id="mvpPipeline" class="pipelineMvp"></div>';const anchor=document.getElementById("mvpToday");anchor?anchor.after(w):hoy.prepend(w);renderMvpDashboard();renderPipeline()}
function saveActions(){localStorage.setItem(TASK_KEY,JSON.stringify(nextActions))}
function addNextAction(clientId,type,date,note){if(!date)return alert("Selecciona la fecha de próxima acción.");if(window.CRMUsers&&!CRMUsers.guard("write",clientId))return;const row={id:(crypto.randomUUID?crypto.randomUUID():Date.now()+"-"+Math.random()),clientId,type:type||"Seguimiento",date,note:note||"",done:false,createdAt:new Date().toISOString(),createdBy:window.CRMUsers?.profile?.().id||""};nextActions.unshift(row);saveActions();window.CRMUsers?.syncTask(row,"next_action");renderTodayMVP();}
function completeAction(id){const x=nextActions.find(a=>a.id===id);if(x){if(window.CRMUsers&&!CRMUsers.guard("write",x.clientId))return;x.done=true;x.doneAt=new Date().toISOString();saveActions();window.CRMUsers?.syncTask(x,"next_action","task_completed");renderTodayMVP()}}
function clientName(c){return c?.cliente||c?.contacto||c?.nombre||c?.email||"Cliente"}
function ds(d){if(!d)return null;return Math.floor((Date.now()-new Date(d).getTime())/86400000)}
function getLast(c){return c.ultimaB2B||c.ultima||c.lastPurchase||c.ultimaCompra||""}
function getCycle(c){return +(c.reorderMedian||c.reorderDays||c.ciclo||c.cycle||0)}
function clientPriority(c){const d=ds(getLast(c)),cy=getCycle(c);if((c.b2bConfirmedOrders||c.pedidos||c.orders||0)===1)return{p:"P1",why:"Activar segunda compra",score:95};if(d!=null&&cy&&d>cy*1.25)return{p:"P1",why:`Recompra atrasada ${Math.max(0,d-cy)} días`,score:90};if(d!=null&&cy&&d>cy*.85)return{p:"P2",why:"Entrando en ventana de recompra",score:70};return{p:"P3",why:"Seguimiento preventivo",score:40}}
function dueActions(){const today=new Date().toISOString().slice(0,10);return nextActions.filter(x=>!x.done&&x.date<=today)}
function buildToday(){const due=dueActions(),ids=new Set(due.map(x=>String(x.clientId)));const arr=[];for(const c of (state?.clients||[])){const pr=clientPriority(c),d=ds(getLast(c)),cy=getCycle(c),inc=alerts().filter(a=>String(a.id)===String(c.id));const urgent=inc.some(a=>a.waiting);if(pr.p==="P1"||pr.p==="P2"||ids.has(String(c.id))||urgent){arr.push({c,pr,d,cy,inc,due:due.filter(x=>String(x.clientId)===String(c.id)),urgent,score:(urgent?120:0)+(ids.has(String(c.id))?110:0)+pr.score})}}return arr.sort((a,b)=>b.score-a.score)}
function renderTodayMVP(){const box=document.getElementById("mvpToday");if(!box)return;const rows=buildToday(),due=dueActions(),urgent=rows.filter(x=>x.urgent).length,pageSize=20,totalPages=Math.max(1,Math.ceil(rows.length/pageSize));if(todayPage>=totalPages)todayPage=totalPages-1;if(todayPage<0)todayPage=0;const visible=rows.slice(todayPage*pageSize,(todayPage+1)*pageSize);box.querySelector(".mvpKpis").innerHTML=[["Para trabajar hoy",rows.length],["Acciones vencidas/hoy",due.length],["P1",rows.filter(x=>x.pr.p==="P1").length],["SKU esperando",urgent]].map(x=>`<div class="kpi"><span>${x[0]}</span><b>${x[1]}</b></div>`).join("");box.querySelector(".mvpRows").innerHTML=visible.map(x=>{const last=getLast(x.c),next=x.cy&&last?new Date(new Date(last).getTime()+x.cy*86400000).toISOString().slice(0,10):"Sin patrón";const rec=x.inc[0];return `<tr data-client="${x.c.id}"><td><span class="v10badge ${x.pr.p==="P1"?"wait":x.pr.p==="P2"?"soon":"now"}">${x.pr.p}</span><br><b>${esc(clientName(x.c))}</b></td><td>${esc(x.pr.why)}${x.due.length?'<br><b class="overdue">Próxima acción pendiente</b>':""}</td><td>${last||"—"}<br><small>${x.d==null?"":x.d+" días"}</small></td><td>${x.cy?x.cy+" días":"Sin patrón"}<br><small>Esperada: ${next}</small></td><td>${rec?`<b>${esc(rec.sku)}</b><br><small>${esc(rec.product||"")} · ${rec.waiting?"CLIENTE ESPERANDO":"por llegar"}</small>`:"Revisar surtido BC > 30"}</td><td><button class="miniOpen" data-open="${x.c.id}">Gestionar</button></td></tr>`}).join("")||'<tr><td colspan="6">No hay acciones prioritarias para hoy.</td></tr>';const pg=box.querySelector(".todayPager");if(pg){pg.innerHTML=`<button class="soft prevPage" ${todayPage===0?"disabled":""}>‹ Anterior</button><span>Mostrando <b>${rows.length?todayPage*pageSize+1:0}–${Math.min((todayPage+1)*pageSize,rows.length)}</b> de <b>${rows.length}</b> · Página ${todayPage+1}/${totalPages}</span><button class="soft nextPage" ${todayPage>=totalPages-1?"disabled":""}>Siguiente ›</button>`;pg.querySelector(".prevPage").onclick=()=>{todayPage--;renderTodayMVP()};pg.querySelector(".nextPage").onclick=()=>{todayPage++;renderTodayMVP()}}box.querySelectorAll("[data-open]").forEach(b=>b.onclick=e=>{e.stopPropagation();const id=+b.dataset.open;if(typeof openClient==="function")openClient(id)})}
function addTodayMVP(){const hoy=document.getElementById("hoy");if(!hoy||document.getElementById("mvpToday"))return;const box=document.createElement("div");box.id="mvpToday";box.className="mvpToday";box.innerHTML='<div class="mvpTitle"><div><small>MVP OPERATIVO</small><h2>Mi Día · Qué trabajar hoy</h2><p>Prioriza recompra, acciones pendientes y clientes esperando mercadería.</p></div></div><div class="kpis mvpKpis"></div><div class="todayScroll"><table><thead><tr><th>Prioridad / cliente</th><th>Por qué hoy</th><th>Última compra</th><th>Ciclo / próxima</th><th>Qué revisar</th><th>Acción</th></tr></thead><tbody class="mvpRows"></tbody></table></div><div class="todayPager"></div>';hoy.prepend(box);renderTodayMVP()}
function injectPipeline360(){const panel=document.getElementById("clientPanel")||document.querySelector(".drawer");if(!panel||panel.dataset.pipeObserver)return;panel.dataset.pipeObserver="1";new MutationObserver(()=>{const detail=document.getElementById("clientDetail")||panel;if(detail.querySelector(".pipe360"))return;const email=[...detail.querySelectorAll("p,small,span,div")].map(x=>x.textContent).find(x=>/@/.test(x))||"";const c=(state?.clients||[]).find(x=>email.includes(x.email||""));if(!c)return;const p=pipeOf(c.id),box=document.createElement("div");box.className="pipe360";box.innerHTML=`<h3>Pipeline comercial</h3><p>Estado actual de esta oportunidad.</p><select class="pipeStageSel">${STAGES.map(st=>`<option ${st===p.stage?"selected":""}>${st}</option>`).join("")}</select><input class="pipeAmount" type="number" value="${p.amount||0}" placeholder="Monto si terminó en pedido"><button class="primary pipeSave">Actualizar etapa</button><div class="pipeHint"></div>`;detail.appendChild(box);box.querySelector(".pipeSave").onclick=()=>{const st=box.querySelector(".pipeStageSel").value,am=box.querySelector(".pipeAmount").value;setStage(c.id,st,am);box.querySelector(".pipeHint").textContent="Etapa actualizada: "+st}}).observe(panel,{childList:true,subtree:true})}
function injectNextAction(){const panel=document.getElementById("clientPanel")||document.querySelector(".drawer");if(!panel||panel.dataset.actionObserver)return;panel.dataset.actionObserver="1";new MutationObserver(()=>{const detail=document.getElementById("clientDetail")||panel;if(detail.querySelector(".nextActionBox"))return;const email=[...detail.querySelectorAll("p,small,span,div")].map(x=>x.textContent).find(x=>/@/.test(x))||"";const c=(state?.clients||[]).find(x=>email.includes(x.email||""));if(!c)return;const box=document.createElement("div");box.className="nextActionBox";box.innerHTML='<h3>Próxima acción</h3><p>Cada gestión debe terminar con un siguiente paso y una fecha.</p><select class="nextType"><option>Seguimiento</option><option>Enviar propuesta</option><option>Llamar</option><option>WhatsApp</option><option>Revisar stock</option><option>Confirmar pedido</option><option>Recompra</option></select><input class="nextDate" type="date"><input class="nextNote" placeholder="Detalle de la próxima acción"><button class="primary nextSave">Guardar próxima acción</button><div class="nextList"></div>';detail.appendChild(box);const draw=()=>{box.querySelector(".nextList").innerHTML=nextActions.filter(x=>String(x.clientId)===String(c.id)&&!x.done).sort((a,b)=>a.date.localeCompare(b.date)).map(x=>`<div><b>${esc(x.date)} · ${esc(x.type)}</b><span>${esc(x.note)}</span><button class="miniDone" data-id="${x.id}">Completar</button></div>`).join("")||"<small>Sin próxima acción pendiente.</small>";box.querySelectorAll("[data-id]").forEach(b=>b.onclick=()=>{completeAction(b.dataset.id);draw()})};box.querySelector(".nextSave").onclick=()=>{addNextAction(c.id,box.querySelector(".nextType").value,box.querySelector(".nextDate").value,box.querySelector(".nextNote").value);box.querySelector(".nextNote").value="";draw()};draw()}).observe(panel,{childList:true,subtree:true})}
function addDataQuality(){const sec=document.getElementById("clientes")||document.querySelector('[data-panel="clientes"]');if(!sec||document.getElementById("dataQuality"))return;const cs=state?.clients||[];const confirmed=cs.filter(c=>(c.b2bConfirmedOrders||0)>0).length;const cycle=cs.filter(c=>getCycle(c)>0).length;const noEmail=cs.filter(c=>!c.email).length;const seen=new Set(),dupSet=new Set();cs.forEach(c=>{const e=norm(c.email);if(!e)return;if(seen.has(e))dupSet.add(e);else seen.add(e)});const dups=dupSet.size;const box=document.createElement("div");box.id="dataQuality";box.className="dataQuality";box.innerHTML=`<h3>Control de calidad de cartera</h3><div class="kpis"><div class="kpi"><span>Cuentas cartera</span><b>${cs.length}</b></div><div class="kpi"><span>Compradores confirmados</span><b>${confirmed}</b></div><div class="kpi"><span>Con ciclo calculado</span><b>${cycle}</b></div><div class="kpi"><span>Sin email</span><b>${noEmail}</b></div><div class="kpi"><span>Emails duplicados</span><b>${dups}</b></div></div><p>Los registros incompletos se mantienen visibles para revisión; no se eliminan automáticamente.</p>`;sec.prepend(box)}
