function crmOpenToolsV2(){let modal=document.getElementById("crmToolsModalV2");if(!modal){const tools=[["detectados","Detección B2B","fa-bullseye"],["recompra","Cartera / Recompra","fa-rotate"],["auditoria","Auditoría CRM","fa-clipboard-check"],["pipeline","Pipeline","fa-filter-circle-dollar"],["tareas","Tareas","fa-list-check"],["top20","Top 20 general","fa-ranking-star"],["oportunidades","Oportunidades","fa-lightbulb"]];modal=document.createElement("div");modal.id="crmToolsModalV2";modal.className="crmToolsModalV2";modal.innerHTML=`<div class="crmToolsCardV2" role="dialog" aria-modal="true" aria-labelledby="crmToolsTitle"><div class="crmToolsHeadV2"><div><b id="crmToolsTitle">Más herramientas</b><small>Módulos complementarios del CRM</small></div><button class="crmCloseV2" aria-label="Cerrar">${crmIconV2("close")}</button></div><div class="crmToolsGridV2">${tools.map(([id,label,icon])=>`<button data-tool-tab="${id}"><i class="fa-solid ${icon}" aria-hidden="true"></i><span><b>${label}</b><small>Abrir módulo</small></span>${crmIconV2("arrow")}</button>`).join("")}</div></div>`;document.body.appendChild(modal);modal.querySelector(".crmCloseV2").onclick=()=>modal.classList.remove("open");modal.onclick=e=>{if(e.target===modal)modal.classList.remove("open")};modal.querySelectorAll("[data-tool-tab]").forEach(btn=>btn.onclick=()=>{const tab=[...document.querySelectorAll(".tabs .tab")].find(x=>x.dataset.tab===btn.dataset.toolTab);if(tab){tab.click();crmSetActiveV2("")}modal.classList.remove("open")})}modal.classList.add("open")}
function addPipelineViewport(){
  const host=document.getElementById("kanban");
  if(!host||host.dataset.viewportReady)return;
  host.dataset.viewportReady="1";
  const resizeColumns=()=>requestAnimationFrame(()=>{
    host.querySelectorAll(":scope > .col").forEach(col=>{
      const deals=[...col.querySelectorAll(":scope > .deal")];
      col.classList.toggle("pipelineScrollable",deals.length>20);
      col.removeAttribute("tabindex");
      col.removeAttribute("role");
      col.removeAttribute("aria-label");
      col.style.removeProperty("--pipeline-visible-height");
      if(deals.length<=20)return;
      const bottom=deals[19].offsetTop+deals[19].offsetHeight+9;
      col.style.setProperty("--pipeline-visible-height",Math.ceil(bottom)+"px");
      col.tabIndex=0;
      col.setAttribute("role","region");
      col.setAttribute("aria-label",`${col.querySelector("h3")?.textContent||"Etapa del pipeline"}. Se muestran 20 clientes a la vez; desplázate para ver los demás.`);
    });
  });
  new MutationObserver(resizeColumns).observe(host,{childList:true,subtree:true});
  window.addEventListener("resize",resizeColumns,{passive:true});
  resizeColumns();
}
